create table public.asset (
    "id" bigint generated by default as identity not null,
    "symbol" text not null,
    "name" text not null,
    "logo" text null check (logo ~ '^https?://.*$'),
    "alt_names" text [] default '{}',
    "created_at" timestamp with time zone default current_timestamp
);
--     _                 _     ____       _ _      _           
--    / \   ___ ___  ___| |_  |  _ \ ___ | (_) ___(_) ___  ___ 
--   / _ \ / __/ __|/ _ \ __| | |_) / _ \| | |/ __| |/ _ \/ __|
--  / ___ \\__ \__ \  __/ |_  |  __/ (_) | | | (__| |  __/\__ \
-- /_/   \_\___/___/\___|\__| |_|   \___/|_|_|\___|_|\___||___/
alter table "public"."asset" enable row level security;
revoke
update,
    delete,
    insert on table "public"."asset"
from anon,
    authenticated;
create policy "Enable read access for all users" on "public"."asset" as PERMISSIVE for
SELECT to public using (true);